import {renderHTML as renderFormHTML} from './components/ManualMarkerEntry.svelte.html.js';
import {renderHTML as renderUnitsHTML} from './components/ManualMarkerEntryUnits.svelte.html.js';

// These strings are controller-prepared reference/escaped-action fragments or
// locally compiled owned units. They are never provider HTML or a new input API.
declare const manualEntryOwnedHTML: unique symbol;
export type ManualEntryHTML = string & {readonly [manualEntryOwnedHTML]: true};
const owned = (html: string): ManualEntryHTML => html as ManualEntryHTML;
const text = (value: unknown): string => value == null ? '' : String(value);
const OPEN = '<!--[-->', CLOSE = '<!--]-->', EMPTY = '<!---->';
const REFERENCE_SLOT = 'getbased-manual-entry-private-reference';
const UNIT_SLOT = 'getbased-manual-entry-private-units';

export interface ManualEntryUnitsView {
  multiple: boolean;
  rows: {value: string; label: string; selected: boolean}[];
  unit: string;
}
export interface ManualEntryView {
  category: string; name: string; unit: string; date: string; today: string;
  placeholder: string; sampleTime: string; fasting: string;
  reference: ManualEntryHTML; unitPicker: ManualEntryHTML;
}
export interface ManualEntryInput {
  category: () => unknown; closeAction: () => string; name: () => unknown;
  unit: () => unknown; reference: string; date: string; today: string;
  unitPicker: ManualEntryHTML; placeholder: unknown; sampleTime: unknown;
  fasting: string; saveAction: () => string; addAction: () => string;
  cancelAction: () => string;
}
export function projectManualEntryUnits(options: readonly unknown[], fallback: () => unknown): ManualEntryUnitsView {
  if (options.length > 1) {
    const rows = options.map((unit, index) => {
      const value = text(unit);
      const label = text(unit); // Original option coerces the unit independently twice.
      return {value, label, selected: index === 0};
    });
    return {multiple: true, rows, unit: ''};
  }
  return {multiple: false, rows: [], unit: text(fallback())};
}
function ownedEnvelope(html: string): string {
  if (!html.startsWith(OPEN) || !html.endsWith(CLOSE))
    throw new Error('Unexpected manual-entry SSR envelope');
  return html.slice(OPEN.length, -CLOSE.length);
}
// Svelte internal utils.hash() and html() use this exact DEV checksum law.
// It qualifies only the private sentinel, never any inserted child data.
function checksum(value: string): string {
  let hash = 5381, i = value.length;
  while (i) hash = ((hash << 5) - hash) ^ value.charCodeAt(--i);
  return (hash >>> 0).toString(36);
}
function slotEnvelope(skeleton: string, sentinel: string): string {
  const production = EMPTY + sentinel + EMPTY;
  const development = '<!--' + checksum(sentinel) + '-->' + sentinel + EMPTY;
  const matches = [production, development].filter(envelope => skeleton.includes(envelope));
  if (matches.length !== 1 || skeleton.indexOf(matches[0]!) !== skeleton.lastIndexOf(matches[0]!))
    throw new Error('Unexpected manual-entry private HTML slot');
  return matches[0]!;
}
const ACTION_TAGS = [
  ['<button class="modal-close" aria-label="Back to marker details" ', '>'],
  ['<button class="import-btn import-btn-primary" ', '>'],
  ['<button class="import-btn import-btn-secondary" ', ' title="Save this value, then enter another marker for the same date">'],
  ['<button class="import-btn import-btn-secondary" ', '>'],
] as const;
function actionSlot(index: number, attributes: string): [string, string] {
  const tag = ACTION_TAGS[index];
  if (!tag) throw new Error('Unknown manual-entry action slot');
  const [prefix, suffix] = tag;
  const marker = `data-manual-entry-private-action="getbased-manual-entry-action-${index}"`;
  // Full opening-tag qualification cannot collide with escaped label text.
  return [prefix + marker + suffix, prefix + attributes + suffix];
}
function validateAction(html: string, action: string): string {
  // The original action helper emits one fixed action plus its escaped ID.
  // The ID is already nonempty at the validated marker path. No extra attrs.
  const prefix = `data-marker-detail-action="${action}" data-marker-detail-id="`;
  if (!html.startsWith(prefix) || !html.endsWith('"') || /["<>]/.test(html.slice(prefix.length, -1)))
    throw new Error('Unexpected manual-entry delegated action fragment');
