  return owned(ownedEnvelope(renderUnitsHTML({view: projectManualEntryUnits(options, fallback)})));
}
export function renderManualMarkerEntry(input: ManualEntryInput): string {
  // Callbacks preserve original template-position reads after unit rendering.
  // In particular category → close attrs → name → unit → tail actions must not
  // be eagerly read while constructing the controller's input object.
  const category = text(input.category());
  const close = validateAction(input.closeAction(), 'show-detail-modal');
  const name = text(input.name());
  const unit = text(input.unit());
  const placeholder = text(input.placeholder);
  const sampleTime = text(input.sampleTime);
  const save = validateAction(input.saveAction(), 'save-manual-entry');
  const add = validateAction(input.addAction(), 'save-and-add-manual-entry');
  const cancel = validateAction(input.cancelAction(), 'show-detail-modal');
  const view: ManualEntryView = {category, name, unit, date: input.date, today: input.today,
    placeholder, sampleTime, fasting: input.fasting,
    reference: owned(REFERENCE_SLOT), unitPicker: owned(UNIT_SLOT)};
  const skeleton = ownedEnvelope(renderFormHTML({view}));
  const replacements = [
    [slotEnvelope(skeleton, REFERENCE_SLOT), input.reference],
    [slotEnvelope(skeleton, UNIT_SLOT), input.unitPicker],
    ...[close, save, add, cancel].map((html, index) => actionSlot(index, html)),
  ];
