  // No replaceAll, raw-child rescanning, DOM rewriting, or whitespace joining.
  const edits = replacements.map(([needle, html]) => {
    if (!needle || html === undefined) throw new Error('Missing manual-entry private slot');
    const start = skeleton.indexOf(needle);
    if (start < 0 || skeleton.lastIndexOf(needle) !== start) throw new Error('Repeated manual-entry private slot');
    return {start, end: start + needle.length, html};
  }).sort((a, b) => a.start - b.start);
  let result = '', cursor = 0;
  for (const edit of edits) {
    if (edit.start < cursor) throw new Error('Overlapping manual-entry private slots');
    result += skeleton.slice(cursor, edit.start) + edit.html;
    cursor = edit.end;
  }
  return result + skeleton.slice(cursor);
}

