import {renderHTML as renderFormHTML} from './components/CustomMarkerForm.svelte.html.js';
import {renderHTML as renderOptionsHTML} from './components/CustomMarkerOptions.svelte.html.js';
import {escapeHTML} from './utils.js';
import {markerDetailActionAttrs} from './marker-detail-actions.js';

declare const customMarkerOptionsHTML: unique symbol;
export type CustomMarkerOptionsHTML = string & {readonly [customMarkerOptionsHTML]: true};
export interface CustomMarkerOptionSkeleton {value: string; label: string}
export interface CustomMarkerCategory {label?: unknown}
interface Slot {coordinate: string; value: string}
const OPTIONS = 'gb-custom-marker-options';

function replaceCoordinate(html: string, coordinate: string, replacement: string): string {
    const at = html.indexOf(coordinate);
    if (at < 0 || html.indexOf(coordinate, at + coordinate.length) !== -1) {
        throw new Error('Unqualified Custom Marker compiler coordinate');
    }
    return html.slice(0, at) + replacement + html.slice(at + coordinate.length);
}
function removeRoot(html: string, prefix: string, suffix: string): string {
    if (!html.startsWith('<!--[-->' + prefix) || !html.endsWith(suffix + '<!--]-->')) {
        throw new Error('Unqualified Custom Marker SSR root');
    }
    return html.slice('<!--[-->'.length, -'<!--]-->'.length);
}
/** Validate the private skeleton first, then insert all rows/actions atomically.
 * Neither raw category keys nor escaped labels are ever rescanned. */
function insert(html: string, slots: readonly Slot[]): string {
    if (html.includes('<!--') || html.includes('<!>')) {
        throw new Error('Unqualified Custom Marker compiler marker');
    }
    const edits = slots.map(({coordinate, value}) => {
        const at = html.indexOf(coordinate);
        if (at < 0 || html.indexOf(coordinate, at + coordinate.length) !== -1) {
            throw new Error('Unqualified Custom Marker private slot');
        }
        return {at, end: at + coordinate.length, value};
    }).sort((a, b) => a.at - b.at);
    let output = '', cursor = 0;
    for (const edit of edits) {
        if (edit.at < cursor) throw new Error('Overlapping Custom Marker private slots');
        output += html.slice(cursor, edit.at) + edit.value;
        cursor = edit.end;
    }
    return output + html.slice(cursor);
}

export function renderCustomMarkerOptions(categories: Record<string, CustomMarkerCategory>): CustomMarkerOptionsHTML {
    const slots: Slot[] = [];
    // Object.entries reads category values before any label coercion, just as in
    // the original controller. Keys already are strings and retain its raw
    // attribute interpolation; labels retain the original escapeHTML call.
    const rows = Object.entries(categories).map(([key, category], index) => {
        const label = escapeHTML(category.label);
        const valueToken = 'gb-custom-marker-option-' + index + '-value';
        const labelToken = 'gb-custom-marker-option-' + index + '-label';
        slots.push({coordinate: '<option value="' + valueToken + '">', value: '<option value="' + key + '">'},
            {coordinate: labelToken, value: label});
        return {value: valueToken, label: labelToken};
    });
    let html = removeRoot(renderOptionsHTML({rows}), '<!--[-->', '<!--]-->');
    if (!rows.length) html = replaceCoordinate(html, '<!--[--><!--]-->', '');
    else {
        html = replaceCoordinate(html, '<!--[--><option value="' + rows[0]!.value + '"', '<option value="' + rows[0]!.value + '"');
        const last = rows[rows.length - 1]!;
        html = replaceCoordinate(html, last.label + '</option><!--]-->', last.label + '</option>');
    }
    return insert(html, slots) as CustomMarkerOptionsHTML;
}

function action(prefix: string, suffix: string, name: string): Slot {
    return {coordinate: prefix + 'data-custom-marker-private-action="' + name + '"' + suffix,
        value: prefix + markerDetailActionAttrs(name) + suffix};
}
export function renderCustomMarkerForm(categories: Record<string, CustomMarkerCategory>): string {
    // Keep category reads/escaping before the five original action-helper calls.
    const options = renderCustomMarkerOptions(categories);
    const slots: Slot[] = [
        action('<button class="modal-close" aria-label="Close" ', '>', 'close-modal'),
        action('<select id="cm-category" ', '>', 'toggle-custom-marker-category'),
        action('<span id="cm-new-cat-icon" title="Pick icon" role="button" tabindex="0" data-custom="" ', '>', 'pick-new-cat-icon'),
        action('<button type="button" class="import-btn import-btn-primary" ', '>', 'save-custom-marker'),
        action('<button type="button" class="import-btn import-btn-secondary" ', '>', 'close-modal'),
    ];
    let html = removeRoot(renderFormHTML({options: OPTIONS as CustomMarkerOptionsHTML}), '<div class="gb-modal-head">', '</div>');
    const production = '<!---->' + OPTIONS + '<!---->';
    const development = '<!--' + checksum(OPTIONS) + '-->' + OPTIONS + '<!---->';
    const envelopes = [production, development].filter(value => html.includes(value));
    if (envelopes.length !== 1) throw new Error('Unqualified Custom Marker options envelope');
    html = replaceCoordinate(html, envelopes[0]!, OPTIONS);
    html = replaceCoordinate(html, '\n          <!></select>', '\n          </select>');
    slots.push({coordinate: OPTIONS, value: options});
    return insert(html, slots);
}
// Installed Svelte DEV html() checksum, used solely on the fixed private child.
function checksum(value: string): string {
    let hash = 5381, index = value.length;
    while (index) hash = ((hash << 5) - hash) ^ value.charCodeAt(--index);
    return (hash >>> 0).toString(36);
}

