  it.each(original.map((record,index)=>({record,index})))('retains whole native tree and defaults for original case $index',({record})=>{
    const current=box(renderCustomMarkerForm(record.categories));restoreFixedStyles(current);
    expect(tree(current)).toEqual(tree(box(record.originalHTML)));
  });
  it('reads category values first, then labels in entry order, and preserves coercion failure',()=>{
    const calls:string[]=[];
    const categories={
      get a(){calls.push('a');return {get label(){calls.push('label-a');return {toString(){calls.push('coerce-a');return 'A';}};}};},
      get b(){calls.push('b');return {get label(){calls.push('label-b');throw new Error('native label');}};}
    };
    expect(()=>renderCustomMarkerForm(categories)).toThrow('native label');
    expect(calls).toEqual(['a','b','label-a','coerce-a','label-b']);
  });
  it('does not rescan a raw key or escaped label for private coordinates',()=>{
    expect(renderCustomMarkerOptions({'gb-custom-marker-option-0-value" data-fixture="raw':{label:'gb-custom-marker-option-0-label <!----> $& <>'}}))
      .toBe('<option value="gb-custom-marker-option-0-value" data-fixture="raw">gb-custom-marker-option-0-label &lt;!----&gt; $&amp; &lt;&gt;</option>');
  });
  it.each([
    ['missing root',(raw:string)=>raw.slice(8)],
    ['foreign comment',(raw:string)=>raw.replace('</div>','<!--foreign--></div>')],
    ['wrong action',(raw:string)=>raw.replace('data-custom-marker-private-action="save-custom-marker"','data-custom-marker-private-action="foreign"')],
    ['missing child boundary',(raw:string)=>raw.replace('gb-custom-marker-options<!---->','gb-custom-marker-options')],
    ['missing select boundary',(raw:string)=>raw.replace('<!></select>','</select>')],
    ['duplicate slot',(raw:string)=>raw.replace('gb-custom-marker-options','gb-custom-marker-optionsgb-custom-marker-options')],
  ] as const)('rejects compiler return corruption: %s',(_name,alter)=>{
    fixture.alter=(owner,raw)=>owner==='form'?alter(raw):raw;
    expect(()=>renderCustomMarkerForm({a:{label:'A'}})).toThrow();
  });
  it.each(['style="display:none;position:fixed"','class="unexpected"'])('rejects unqualified fixed attribute mutation: %s',replacement=>{
    const current=box(renderCustomMarkerForm({}));current.querySelector('#cm-new-cat-row')?.setAttribute(replacement.startsWith('style')?'style':'class',replacement.startsWith('style')?'display:none;position:fixed':'unexpected');
    expect(()=>{restoreFixedStyles(current);expect(tree(current)).toEqual(tree(box(original[0]!.originalHTML)));}).toThrow();
  });
});
